package org.azora.lang.backend

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertTrue

/** [LlvmUnits] on module text written the way the code generator writes it. */
class LlvmUnitsTest {
    private val module = """
        ; LLVM IR generated by Azora compiler

        declare i32 @puts(i8*)

        %azora.lambda.ctx.7 = type { i32* }
        %struct.Box = type { i32, %azora.lambda.ctx.7* }

        @counter = internal global i32 0
        @__tl_depth = thread_local global i64 0
        @greeting = global i8* getelementptr ([3 x i8], [3 x i8]* @.str.4, i64 0, i64 0)
        define void @one() { ret void }

        define i32 @first(i32 %x) {
        entry:
          %c = load i32, i32* @counter
          call void @__azora_set_drop(i8* null, void (i8*, i64)* @__azora_drop_pack_12, i64 1)
          %p = getelementptr [6 x i8], [6 x i8]* @.str.9, i64 0, i64 0
          %r = call i32 @puts(i8* %p)
          ret i32 %c
        }

        define void @second(%struct.Box* %env) {
        entry:
          %d = load i64, i64* @__tl_depth
          %v = call i32 @first(i32 1)
          call void @__azora_set_drop(i8* null, void (i8*, i64)* @__azora_drop_pack_12, i64 1)
          ret void
        }

        define void @__azora_drop_pack_12(i8* %raw, i64 %count) {
        entry:
          ret void
        }

        define void @__azora_set_drop(i8* %ptr, void (i8*, i64)* %destroy, i64 %count) {
        entry:
          ret void
        }
        @.str.4 = private unnamed_addr constant [3 x i8] c"hi\00"
        @.str.9 = private unnamed_addr constant [6 x i8] c"a @b;\00"
    """.trimIndent()

    private fun defined(text: String): List<String> =
        Regex("""(?m)^define ([a-z_ ]*?)(?:void|i\d+|i8\*|%\S+) @([A-Za-z0-9_.$-]+)\(""").findAll(text)
            .map { "${it.groupValues[1].trim()}:${it.groupValues[2]}" }.toList()

    @Test
    fun functionsLandInTheirHashedPartAndHelpersAreCopiedWhereUsed() {
        val parts = LlvmUnits.split(module, 4)
        assertEquals(listOf("part-00.ll", "part-01.ll", "part-02.ll", "part-03.ll", LlvmUnits.GLOBALS), parts.map { it.name })
        for (name in listOf("one", "first", "second")) {
            val home = parts[LlvmUnits.partOf(name, 4)]
            assertTrue(":$name" in defined(home.text), "$name defined in ${home.name}:\n${home.text}")
            for (other in parts.filter { it !== home }) assertTrue(":$name" !in defined(other.text), "$name also in ${other.name}")
        }
        // The runtime is linkonce_odr where it is called; a drop function a private copy, renumbered.
        for (part in parts) {
            if ("call void @__azora_set_drop" !in part.text) continue
            val names = defined(part.text)
            assertTrue("linkonce_odr:__azora_set_drop" in names, part.text)
            assertTrue("internal:__azora_drop_pack_0" in names, part.text)
        }
    }

    @Test
    fun variablesAreDefinedOnceAndDeclaredWhereUsed() {
        val parts = LlvmUnits.split(module, 2)
        val globals = parts.last().text
        assertTrue("@counter = global i32 0" in globals, globals)
        assertTrue("@__tl_depth = thread_local global i64 0" in globals, globals)
        // A variable's initializer keeps its constant, copied into this part under its own number.
        assertTrue("@greeting = global i8* getelementptr ([3 x i8], [3 x i8]* @.str.0, i64 0, i64 0)" in globals, globals)
        assertTrue("@.str.0 = private unnamed_addr constant [3 x i8] c\"hi\\00\"" in globals, globals)
        val first = parts[LlvmUnits.partOf("first", 2)].text
        assertTrue("@counter = external global i32" in first, first)
        val second = parts[LlvmUnits.partOf("second", 2)].text
        assertTrue("@__tl_depth = external thread_local global i64" in second, second)
        if (second != first) assertTrue("declare i32 @first(i32)" in second, second)
    }

    @Test
    fun numberedNamesAreRenumberedByThePartAndQuotedTextIsLeftAlone() {
        val part = LlvmUnits.split(module, 1).first().text
        assertTrue("%azora.lambda.ctx.0 = type { i32* }" in part, part)
        assertTrue("%struct.Box = type { i32, %azora.lambda.ctx.0* }" in part, part)
        assertTrue("define void @second(%struct.Box* %env)" in part, part)
        // `@b` inside the string is data, not a symbol to declare.
        assertTrue("c\"a @b;\\00\"" in part, part)
        assertTrue(part.lines().none { it.startsWith("declare") && "@b" in it }, part)
        assertTrue("define void @one() { ret void }" in part, part)
    }

    @Test
    fun aPartsTextDependsOnlyOnTheFunctionsItHolds() {
        // A string added before everything renumbers the module's constants.
        val edited = module
            .replace("@.str.9", "@.str.10").replace("@.str.4", "@.str.5")
            .replace("define void @one() { ret void }", "define void @one() { ret void }\n@.str.4 = private unnamed_addr constant [2 x i8] c\"x\\00\"")
        assertEquals(LlvmUnits.split(module, 3), LlvmUnits.split(edited, 3))
    }

    @Test
    fun aSymbolNothingDeclaresIsRefused() {
        val broken = module.replace("call i32 @puts(i8* %p)", "call i32 @nowhere(i8* %p)")
        assertFailsWith<IllegalStateException> { LlvmUnits.split(broken, 2) }
    }
}
